#include <stdio.h>
#include <string.h>
void q120(){ emp[50];int cnt=0,ch;printf("=== COMPLETE MINI PROJECT ===\n");do{printf("\n1.Add 2.View 3.Search 4.Sort 5.Stats 6.Delete 7.Exit\nChoice: ");scanf("%d",&ch);getchar();if(ch==1){emp[cnt].id=cnt+1;printf("Name: ");fgets(emp[cnt].name,50,stdin);emp[cnt].name[strcspn(emp[cnt].name,"\n")]='\0';printf("Dept: ");fgets(emp[cnt].dept,30,stdin);emp[cnt].dept[strcspn(emp[cnt].dept,"\n")]='\0';printf("Age: ");scanf("%d",&emp[cnt].age);printf("Salary: ");scanf("%f",&emp[cnt].salary);printf("Email: ");scanf("%s",emp[cnt].email);getchar();cnt++;printf("Added!\n");}else if(ch==2){if(!cnt){printf("No records.\n");continue;}printf("%-4s %-20s %-15s %-4s %-10s %s\n","ID","Name","Dept","Age","Salary","Email");for(int i=0;i<cnt;i++)displayE(emp[i]);}else if(ch==3){char k[50];printf("Search name: ");fgets(k,50,stdin);k[strcspn(k,"\n")]='\0';int f=0;for(int i=0;i<cnt;i++)if(strstr(emp[i].name,k)){displayE(emp[i]);f=1;}if(!f)printf("Not found.\n");}else if(ch==4){for(int i=0;i<cnt-1;i++)for(int j=0;j<cnt-i-1;j++)if(emp[j].salary>emp[j+1].salary){Emp t=emp[j];emp[j]=emp[j+1];emp[j+1]=t;}printf("Sorted by salary!\n");}else if(ch==5){if(!cnt){printf("No data.\n");continue;}float mx=emp[0].salary,mn=emp[0].salary,tot=0;for(int i=0;i<cnt;i++){tot+=emp[i].salary;if(emp[i].salary>mx)mx=emp[i].salary;if(emp[i].salary<mn)mn=emp[i].salary;}printf("Total:%d Avg:%.2f Max:%.2f Min:%.2f\n",cnt,tot/cnt,mx,mn);}else if(ch==6){int id;printf("Delete ID: ");scanf("%d",&id);getchar();int pos=-1;for(int i=0;i<cnt;i++)if(emp[i].id==id){pos=i;break;}if(pos==-1)printf("Not found!\n");else{for(int i=pos;i<cnt-1;i++)emp[i]=emp[i+1];cnt--;printf("Deleted!\n");}}}while(ch!=7);printf("Thank you!\n");}